    this.ui.revealed=true;this.ui.feedback={kind:correct?'match':'miss',message:correct?'Beklenen hedef biçimle eşleşti. Şimdi ne kadar yardımsız getirebildiğini kaydet.':'Beklenen hedef biçimle eşleşmedi. '+(task.feedback_scope||'Bu etkinlik kartın hedefini denetler; bütün olası eşanlamlıları veya alternatif cümleleri puanlamaz.')};
