  App.prototype.noteCode = function(q) {if(ERROR_CODES[q.error_code])return q.error_code;var s=searchNorm((q.skill||'')+' '+(q.type||''));if(/kelime|lexical|collocation|phrasal|vocabulary/.test(s))return'K';if(/grammar|gramer|dil bilgisi|tense|modal|relative|article|passive|verb/.test(s))return'G';if(/infer|çıkar|cikar|scope|kapsam/.test(s))return'Ç';if(/refer|gönder|gonder|cohesion|akış|akis/.test(s))return'R';return'B';};
