  App.prototype.submitExam = function(reason) {var e=this.state.exam;if(!e.startedAt||e.submittedAt)return;e.elapsed=reason==='time'?EXAM_LIMIT:this.elapsed();e.runningSince=0;e.submittedAt=Date.now();e.updatedAt=e.submittedAt;e.submissionReason=reason;this.ui.submitConfirm=false;if(!this.state.firstAttempt)this.state.firstAttempt=JSON.parse(JSON.stringify(e));var self=this;this.questions.forEach(function(q){var choice=e.answers[q.id];if(choice!==undefined&&choice!==q.answer)self.questionNote(q,choice,e.confidence[q.id],'PROVA-');});this.activity();this.save();this.render();this.toast(reason==='time'?'Süre tamamlandı; son kayıtlı yanıtların teslim edildi.':'Prova teslim edildi. Yanıtlar sabitlendi; açıklamalar açıldı.');};
  App.prototype.preparePrint = function() {this.root.querySelectorAll('.yds-print-value').forEach(function(x){x.remove();});this.root.querySelectorAll('.yds-note textarea,.yds-note input[type="text"],.yds-note input:not([type]),.yds-note select').forEach(function(el){var p=document.createElement('div');p.className='yds-print-value';p.textContent=el.tagName==='SELECT'?el.options[el.selectedIndex].text:el.value;el.insertAdjacentElement('afterend',p);});};
